package io.github.railgun19457.astrbotadapter.core.auth;

import io.github.railgun19457.astrbotadapter.util.Ids;

import java.security.SecureRandom;
import java.time.Duration;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Manages short-lived SRP-6a registrations generated by administrator commands.
 *
 * <p>The public pairing ID selects a registration. The service retains only an SRP
 * salt and verifier, never the plaintext pairing code after creation returns.</p>
 */
public final class PairingCodeService {
    private static final int CODE_BYTES = 16;
    private static final int MAX_ATTEMPTS = 5;

    private final SecureRandom secureRandom = new SecureRandom();
    private final Map<String, PairingRecord> records = new ConcurrentHashMap<>();

    /**
     * Creates a one-time SRP registration.
     *
     * @param targetId Optional bound peer identifier.
     * @param ttl Maximum registration lifetime.
     * @return The sole result that contains the plaintext pairing code.
     */
    public PairingCode create(String targetId, Duration ttl) {
        cleanupExpired();
        byte[] bytes = new byte[CODE_BYTES];
        secureRandom.nextBytes(bytes);
        String code = Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
        String pairingId = Ids.randomId();
        Srp6aService.Registration registration = Srp6aService.register(Srp6aService.pairingIdentity(pairingId), code);
        PairingRecord record = new PairingRecord(
            pairingId,
            targetId,
            System.currentTimeMillis() + Math.max(1L, ttl.toMillis()),
            0,
            false,
            registration.salt(),
            registration.verifier()
        );
        records.put(record.pairingId(), record);
        return new PairingCode(code, pairingId, targetId, record.expiresAt(), false);
    }

    /**
     * Finds a valid registration without consuming it.
     *
    * @param pairingId Public pairing identifier supplied by the client.
     * @param targetId Client identity checked against an optional target binding.
     * @return Detailed result and SRP registration when valid.
     */
    public LookupResult lookup(String pairingId, String targetId) {
        return inspect(pairingId, targetId, false);
    }

    /**
     * Atomically consumes a registration after SRP and key enrollment both succeed.
     *
    * @param pairingId Public pairing identifier supplied by the client.
     * @param targetId Client identity checked against an optional target binding.
     * @return Detailed result and SRP registration when consumption succeeds.
     */
    public LookupResult consume(String pairingId, String targetId) {
        return inspect(pairingId, targetId, true);
    }

    private LookupResult inspect(String pairingId, String targetId, boolean consume) {
        if (pairingId == null || pairingId.isBlank()) {
            return new LookupResult(VerificationStatus.MISSING, null);
        }
        LookupResult[] result = new LookupResult[1];
        records.compute(pairingId, (ignored, record) -> {
            if (record == null) {
                result[0] = new LookupResult(VerificationStatus.MISSING, null);
                return null;
            }
            if (record.expiresAt() < System.currentTimeMillis()) {
                result[0] = new LookupResult(VerificationStatus.EXPIRED, record);
                return null;
            }
            if (record.used()) {
                result[0] = new LookupResult(VerificationStatus.USED, record);
                return record;
            }
            if (targetId != null && record.targetId() != null && !targetId.equals(record.targetId())) {
                result[0] = new LookupResult(VerificationStatus.TARGET_MISMATCH, record);
                return record;
            }
            if (record.attempts() >= MAX_ATTEMPTS) {
                result[0] = new LookupResult(VerificationStatus.ATTEMPTS_EXCEEDED, record);
                return null;
            }
            if (consume) {
                PairingRecord used = record.withUsed();
                result[0] = new LookupResult(VerificationStatus.OK, used);
                return used;
            }
            result[0] = new LookupResult(VerificationStatus.OK, record);
            return record;
        });
        return result[0];
    }

    /**
     * Counts a failed proof towards the bounded pairing attempt limit.
     *
     * @param pairingId Public pairing identifier supplied by the client.
     */
    public void recordFailedAttempt(String pairingId) {
        if (pairingId == null || pairingId.isBlank()) {
            return;
        }
        records.computeIfPresent(pairingId, (ignored, record) -> {
            if (record.expiresAt() < System.currentTimeMillis() || record.used()) {
                return record;
            }
            return record.withFailedAttempt();
        });
    }

    /**
     * Returns administrative metadata without revealing codes or verifiers.
     *
    * @return Pending pairing records keyed by public pairing ID.
     */
    public Map<String, PairingCode> list() {
        cleanupExpired();
        Map<String, PairingCode> result = new LinkedHashMap<>();
        records.values().forEach(record -> result.put(record.pairingId(), record.toMetadata()));
        return Map.copyOf(result);
    }

    public boolean revoke(String pairingId) {
        if (pairingId == null || pairingId.isBlank()) {
            return false;
        }
        return records.remove(pairingId) != null;
    }

    private void cleanupExpired() {
        long now = System.currentTimeMillis();
        records.entrySet().removeIf(entry -> entry.getValue().expiresAt() < now);
    }

    public record PairingCode(String code, String pairingId, String targetId, long expiresAt, boolean used) {
    }

    public record PairingRecord(
        String pairingId,
        String targetId,
        long expiresAt,
        int attempts,
        boolean used,
        String salt,
        String verifier
    ) {
        private PairingRecord withUsed() {
            return new PairingRecord(pairingId, targetId, expiresAt, attempts, true, salt, verifier);
        }

        private PairingRecord withFailedAttempt() {
            return new PairingRecord(pairingId, targetId, expiresAt, attempts + 1, false, salt, verifier);
        }

        private PairingCode toMetadata() {
            return new PairingCode(null, pairingId, targetId, expiresAt, used);
        }

        public Srp6aService.Registration registration() {
            return new Srp6aService.Registration(salt, verifier);
        }
    }

    public enum VerificationStatus {
        OK,
        MISSING,
        USED,
        EXPIRED,
        TARGET_MISMATCH,
        ATTEMPTS_EXCEEDED
    }

    public record LookupResult(VerificationStatus status, PairingRecord record) {
    }
}
